% findall_3.pl: ISO Prolog conformance vectors, from Logtalk's tests
% (tests/prolog/predicates and tests/prolog/control of
% https://github.com/LogtalkDotOrg/logtalk3), which are
%   SPDX-FileCopyrightText: 1998-2026 Paulo Moura <pmoura@logtalk.org>
%   SPDX-License-Identifier: Apache-2.0
% and carry the examples of the ISO/IEC 13211-1 standard and of the
% conformance testing framework of Peter Szabo and Peter Szeredi.
% Generated by lang/stralog/tests/mkiso.py: v(Name, Expected, Goal).

f(_, 1).
f(_, 2).

v(iso_findall_3_01, true(S == [1,2]), (findall(X, (X=1;X=2), S))).
v(iso_findall_3_03, true(L == []), (findall(_X, fail, L))).
v(iso_findall_3_04, true(S == [1,1]), (findall(X, (X=1;X=1), S))).
v(iso_findall_3_05, false, (findall(X, (X=2;X=1), [1,2]))).
v(iso_findall_3_06, true(X-Y == 1-2), (findall(X, (X=1;X=2), [X,Y]))).
v(iso_findall_3_07, error(instantiation_error), (findall(_X, _Goal, _S))).
v(sics_findall_3_09, error(type_error(list,[A|1])), (findall(X, X=1, [A|1]))).
v(eclipse_findall_3_10, error(type_error(list,12)), (findall(X, (X=2; X=1), 12))).
v(lgt_findall_3_12, true(V1 \== V2), (findall(g(_, X), f(_, X), [g(V1, _), g(V2, _)]))).
v(lgt_findall_3_14, ball(err), (findall(X, (X = 1; throw(err)), _))).
